import { useState } from 'react';
import {
  JxCard,
  JxSteps,
  JxStep,
  JxFormField,
  JxInput,
  JxButton,
  JxStack,
  JxDivider,
  JxText,
} from '@jinx-ui/react';

type ContactData = {
  fullName: string;
  email: string;
  phone: string;
};

type AddressData = {
  country: string;
  city: string;
  street: string;
  zip: string;
};

type RegistrationData = {
  contact: ContactData;
  address: AddressData;
};

type RegistrationFormProps = {
  onSubmit: (data: RegistrationData) => void;
};

const STEP_LABELS = ['Контакты', 'Адрес', 'Проверка'];

export default function RegistrationForm({ onSubmit }: RegistrationFormProps) {
  const [currentStep, setCurrentStep] = useState(0);

  const [contact, setContact] = useState<ContactData>({
    fullName: '',
    email: '',
    phone: '',
  });

  const [address, setAddress] = useState<AddressData>({
    country: '',
    city: '',
    street: '',
    zip: '',
  });

  const isLastStep = currentStep === STEP_LABELS.length - 1;
  const isFirstStep = currentStep === 0;

  const handleNext = () => {
    if (!isLastStep) {
      setCurrentStep((step) => step + 1);
    }
  };

  const handleBack = () => {
    if (!isFirstStep) {
      setCurrentStep((step) => step - 1);
    }
  };

  const handleSubmit = () => {
    onSubmit({ contact, address });
  };

  return (
    <JxCard className="jx-p-lg" style={{ maxWidth: 480 }}>
      <JxStack direction="column" gap="lg">
        <JxSteps activeIndex={currentStep}>
          {STEP_LABELS.map((label, index) => (
            <JxStep key={label} label={label} status={index < currentStep ? 'completed' : index === currentStep ? 'active' : 'pending'} />
          ))}
        </JxSteps>

        <JxDivider />

        {currentStep === 0 && (
          <JxStack direction="column" gap="md">
            <JxFormField label="Полное имя">
              <JxInput
                value={contact.fullName}
                onChange={(e) => setContact({ ...contact, fullName: e.target.value })}
                placeholder="Иван Иванов"
              />
            </JxFormField>
            <JxFormField label="Email">
              <JxInput
                type="email"
                value={contact.email}
                onChange={(e) => setContact({ ...contact, email: e.target.value })}
                placeholder="name@example.com"
              />
            </JxFormField>
            <JxFormField label="Телефон">
              <JxInput
                type="tel"
                value={contact.phone}
                onChange={(e) => setContact({ ...contact, phone: e.target.value })}
                placeholder="+7 900 000-00-00"
              />
            </JxFormField>
          </JxStack>
        )}

        {currentStep === 1 && (
          <JxStack direction="column" gap="md">
            <JxFormField label="Страна">
              <JxInput
                value={address.country}
                onChange={(e) => setAddress({ ...address, country: e.target.value })}
                placeholder="Россия"
              />
            </JxFormField>
            <JxFormField label="Город">
              <JxInput
                value={address.city}
                onChange={(e) => setAddress({ ...address, city: e.target.value })}
                placeholder="Москва"
              />
            </JxFormField>
            <JxFormField label="Улица, дом">
              <JxInput
                value={address.street}
                onChange={(e) => setAddress({ ...address, street: e.target.value })}
                placeholder="ул. Ленина, д. 1"
              />
            </JxFormField>
            <JxFormField label="Индекс">
              <JxInput
                value={address.zip}
                onChange={(e) => setAddress({ ...address, zip: e.target.value })}
                placeholder="123456"
              />
            </JxFormField>
          </JxStack>
        )}

        {currentStep === 2 && (
          <JxStack direction="column" gap="md">
            <JxText weight="bold">Проверьте данные перед отправкой</JxText>

            <JxStack direction="column" gap="xs">
              <JxText color="secondary">Контакты</JxText>
              <JxText>{contact.fullName || '—'}</JxText>
              <JxText>{contact.email || '—'}</JxText>
              <JxText>{contact.phone || '—'}</JxText>
            </JxStack>

            <JxDivider />

            <JxStack direction="column" gap="xs">
              <JxText color="secondary">Адрес</JxText>
              <JxText>{address.country || '—'}</JxText>
              <JxText>{address.city || '—'}</JxText>
              <JxText>{address.street || '—'}</JxText>
              <JxText>{address.zip || '—'}</JxText>
            </JxStack>
          </JxStack>
        )}

        <JxDivider />

        <JxStack direction="row" justify="space-between">
          <JxButton variant="secondary" onClick={handleBack} disabled={isFirstStep}>
            Назад
          </JxButton>

          {isLastStep ? (
            <JxButton variant="primary" onClick={handleSubmit}>
              Отправить
            </JxButton>
          ) : (
            <JxButton variant="primary" onClick={handleNext}>
              Дальше
            </JxButton>
          )}
        </JxStack>
      </JxStack>
    </JxCard>
  );
}

